import * as React from "react"
import { cn } from "@/lib/utils"

interface BlobProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: "sm" | "md" | "lg"
  color?: string
}

export function Blob({ 
  className, 
  size = "md",
  color = "var(--accent, #6a8c3f)",
  ...props 
}: BlobProps) {
  const sizes = {
    sm: "w-16 h-16",
    md: "w-24 h-24",
    lg: "w-32 h-32",
  }

  return (
    <div 
      className={cn(
        "rounded-full",
        sizes[size],
        className
      )}
      style={{
        background: color,
        animation: "blob-drift 16s ease-in-out infinite",
      }}
      {...props}
    />
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface MossCardProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string
  description?: string
}

export function MossCard({ 
  className, 
  title = "Organic Growth",
  description = "Natural patterns emerge from simple rules. Watch the garden grow.",
  ...props 
}: MossCardProps) {
  return (
    <div 
      className={cn("p-5 border rounded-xl", className)}
      style={{
        background: "var(--surface, var(--card))",
        border: "1px solid var(--border, #d4c9b8)",
      }}
      {...props}
    >
      <h3 
        className="text-xl font-semibold mb-2 tracking-tight"
        style={{ 
          fontFamily: "var(--font-display, 'Fraunces', serif)",
          color: "var(--fg, var(--foreground))",
        }}
      >
        {title}
      </h3>
      <p 
        className="text-sm leading-relaxed"
        style={{ color: "var(--fg-muted, var(--muted-foreground))" }}
      >
        {description}
      </p>
    </div>
  )
}

@keyframes blob-drift {
  0%, 100% { transform: translate(0, 0) scale(1); }
  33% { transform: translate(10px, -10px) scale(1.05); }
  66% { transform: translate(-5px, 5px) scale(0.95); }
}
